export const GREETING_INDEX_GLOBAL_KEY = 'DhlGreetingIndex';
export const GREETING_INDEX_CHANNEL = 'denghuolanshan:greeting-index';
export const GREETING_INDEX_SCRIPT_NAME = '开场白索引';
export const GREETING_INDEX_DEV_IMPORT = "import 'http://127.0.0.1:5502/dist/开场白索引/index.js';";
export const GREETING_INDEX_CDN_IMPORT = "import 'https://testingcf.jsdelivr.net/gh/Alice233-Alice/Apeiria@main/开场白索引/index.js';";

export type GreetingIndexViewMode = 'heroine' | 'all';

export interface GreetingIndexOpenOptions {
  heroine?: string;
  view?: GreetingIndexViewMode;
  locateCurrent?: boolean;
  query?: string;
}

export interface GreetingIndexGlobalApi {
  version: number;
  open: (options?: GreetingIndexOpenOptions) => Promise<void> | void;
  close: () => void;
  toggle: (options?: GreetingIndexOpenOptions) => Promise<void> | void;
  isOpen: () => boolean;
}

export type GreetingIndexMessage =
  | {
      channel: typeof GREETING_INDEX_CHANNEL;
      type: 'open';
      options?: GreetingIndexOpenOptions;
    }
  | {
      channel: typeof GREETING_INDEX_CHANNEL;
      type: 'close';
    }
  | {
      channel: typeof GREETING_INDEX_CHANNEL;
      type: 'toggle';
      options?: GreetingIndexOpenOptions;
    };

export function isGreetingIndexMessage(value: unknown): value is GreetingIndexMessage {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  return (
    record.channel === GREETING_INDEX_CHANNEL &&
    (record.type === 'open' || record.type === 'close' || record.type === 'toggle')
  );
}
