import { compareRealmStanding, type SchemaType } from '../schema';

export type CombatState = SchemaType['本尊']['战斗状态'];
export type BattlePhase = CombatState['阶段'];
export type BattleMomentum = CombatState['战局']['态势'];
export type EssenceBurden = CombatState['负荷']['真元'];
export type SoulBurden = CombatState['负荷']['神识'];
export type BodyBurden = CombatState['负荷']['肉身'];
export type EnemyRecord = SchemaType['本尊']['当前敌人'];
export type EnemyInfo = EnemyRecord[string];
export type EnemyState = EnemyInfo['状态'];
export type TribulationState = SchemaType['本尊']['渡劫状态'];
export type BurdenTone = 'clear' | 'steady' | 'strained' | 'critical';
export type CombatStageMode = 'tribulation' | 'battle' | 'peace';

const INACTIVE_ENEMY_STATES = new Set<EnemyState>(['失能', '退走', '被擒', '败亡']);
const ACTIVE_BATTLE_PHASES = new Set<BattlePhase>(['对峙', '试探', '交锋', '决胜', '脱战']);

export const isEnemyActive = (enemy: EnemyInfo): boolean => !INACTIVE_ENEMY_STATES.has(enemy.状态);

export const resolveCombatStageMode = (
  protagonist: Pick<SchemaType['本尊'], '战斗状态' | '当前敌人' | '渡劫状态'>,
): { mode: CombatStageMode; isInRecovery: boolean } => {
  const { 战斗状态: combatState, 当前敌人: currentEnemies, 渡劫状态: tribulationState } = protagonist;
  if (tribulationState.正在渡劫) {
    return { mode: 'tribulation', isInRecovery: false };
  }
  const hasActiveEnemies = Object.values(currentEnemies).some(isEnemyActive);
  if (
    combatState.正在战斗 ||
    ACTIVE_BATTLE_PHASES.has(combatState.阶段) ||
    (hasActiveEnemies && combatState.交锋轮次 > 0)
  ) {
    return { mode: 'battle', isInRecovery: false };
  }
  const burdens = combatState.负荷;
  const burdened = burdens.真元 !== '充盈' || burdens.神识 !== '澄明' || burdens.肉身 !== '无恙';
  const recentResult = combatState.最近战果;
  const hasBattleResult =
    recentResult.结果 !== '无' ||
    recentResult.代价.length > 0 ||
    recentResult.后患.length > 0 ||
    Boolean(recentResult.达成.trim());
  const battleAftermath = combatState.阶段 === '余波' && hasBattleResult;
  const tribAftermath = tribulationState.劫力承受 < 100;
  const usedProtection = tribulationState.已用护道.length > 0;
  const recentTribResult = tribulationState.上次渡劫结果 !== '无';
  return {
    mode: 'peace',
    isInRecovery: Boolean(
      burdened || battleAftermath || tribAftermath || usedProtection || recentTribResult || hasActiveEnemies,
    ),
  };
};

export const getRealmStanding = (playerLevel: number, enemy: EnemyInfo): string =>
  compareRealmStanding(playerLevel, enemy.等级);

export const getRealmStandingTone = (standing: string): 'safe' | 'easy' | 'equal' | 'hard' | 'deadly' => {
  if (standing.startsWith('我方位格') || standing.includes('近乎碾压')) return 'safe';
  if (standing.startsWith('我方')) return 'easy';
  if (standing === '同阶') return 'equal';
  if (standing.startsWith('敌方位格') || standing.startsWith('敌方近乎')) return 'deadly';
  return 'hard';
};

export const getEnemyStateIcon = (state: EnemyState): string => {
  const icons: Record<EnemyState, string> = {
    全盛: 'fa-solid fa-shield',
    受制: 'fa-solid fa-link',
    负伤: 'fa-solid fa-bandage',
    重创: 'fa-solid fa-heart-crack',
    失能: 'fa-solid fa-ban',
    退走: 'fa-solid fa-person-running',
    被擒: 'fa-solid fa-handcuffs',
    败亡: 'fa-solid fa-skull-crossbones',
  };
  return icons[state];
};

const CANONICAL_BURDEN_TONES: Record<string, BurdenTone> = {
  充盈: 'clear',
  澄明: 'clear',
  无恙: 'clear',
  尚足: 'steady',
  疲乏: 'steady',
  轻创: 'steady',
  吃紧: 'strained',
  动荡: 'strained',
  重创: 'strained',
  枯竭: 'critical',
  受创: 'critical',
  濒危: 'critical',
};

const DESCRIPTIVE_BURDEN_PATTERNS: Array<{ tone: BurdenTone; pattern: RegExp }> = [
  { tone: 'clear', pattern: /充盈|澄明|无恙|无伤|完好|平稳|安然|痊愈/gu },
  { tone: 'steady', pattern: /尚足|疲乏|疲惫|轻创|轻伤|小伤|微伤|轻损|小损|微损|略耗|消耗|擦伤|不稳/gu },
  { tone: 'strained', pattern: /吃紧|动荡|震荡|重创|重伤|伤重|中损|中创|受损|负伤|受伤|剧耗|大损|紊乱|反噬|迸裂/gu },
  { tone: 'critical', pattern: /枯竭|耗尽|濒危|濒死|垂危|危殆|将死|命悬|识海崩|神魂崩/gu },
];

export const getBurdenTone = (value: string): BurdenTone => {
  const description = String(value ?? '').trim();
  if (!description) return 'clear';
  if (CANONICAL_BURDEN_TONES[description]) return CANONICAL_BURDEN_TONES[description];

  let lastMatchIndex = -1;
  let inferredTone: BurdenTone | null = null;
  for (const { tone, pattern } of DESCRIPTIVE_BURDEN_PATTERNS) {
    pattern.lastIndex = 0;
    for (const match of description.matchAll(pattern)) {
      if ((match.index ?? -1) >= lastMatchIndex) {
        lastMatchIndex = match.index ?? -1;
        inferredTone = tone;
      }
    }
  }

  // 非空的未知描述代表“存在状态信息”，不能再按健康状态显示。
  return inferredTone ?? 'strained';
};

export const getBurdenSegments = (tone: BurdenTone): number => {
  const map: Record<BurdenTone, number> = {
    clear: 4,
    steady: 3,
    strained: 2,
    critical: 1,
  };
  return map[tone];
};

export const getBurdenStatusLabel = (tone: BurdenTone): string => {
  const map: Record<BurdenTone, string> = {
    clear: '安然',
    steady: '微耗',
    strained: '吃紧',
    critical: '危殆',
  };
  return map[tone];
};

export const getTribulationTypeColor = (type: string) => {
  const colors: Record<string, string> = {
    无: 'var(--text-secondary)',
    雷劫: 'var(--tier-mystic, var(--semantic-info))',
    心劫: 'var(--semantic-relation)',
    天劫: 'var(--tier-heaven, var(--gold))',
    情劫: 'var(--semantic-relation)',
    因果劫: 'var(--semantic-info)',
    红尘劫: 'var(--tier-yellow, var(--semantic-warning))',
    轮回劫: 'var(--tier-earth, var(--jade))',
  };
  return colors[type] || 'var(--tier-mystic, var(--gold))';
};

export const getTribulationLevelColor = (level: string) => {
  const colors: Record<string, string> = {
    无: 'var(--text-secondary)',
    小劫: 'var(--jade)',
    中劫: 'var(--tier-yellow, var(--semantic-warning))',
    大劫: 'var(--tier-heaven, var(--gold))',
    天罚: 'var(--semantic-danger)',
  };
  return colors[level] || 'var(--gold)';
};
