/** 行动已有句末标点时沿用原句，避免拼接出重复句号。 */
export function ensureSentence(text: string): string {
  const sentence = text.trim();
  return sentence && !/[。！？!?…]$/u.test(sentence) ? sentence + '。' : sentence;
}

const ZH_NUMBER_FORMATTER = new Intl.NumberFormat('zh-CN');

export function formatZhNumber(value: number): string {
  return ZH_NUMBER_FORMATTER.format(value);
}

export function formatDurationSeconds(durationMs: number): string {
  return `${Math.max(1, Math.round(durationMs / 1000))} 秒`;
}

export function splitParenText(rawValue: string, fallback = '未知'): { title: string; detail: string } {
  const text = rawValue.trim() || fallback;
  const match = /^([^（(]+?)\s*[（(]([\s\S]+)[）)]$/.exec(text);
  if (match) {
    return {
      title: match[1].trim() || text,
      detail: match[2].replace(/[）)]$/u, '').trim(),
    };
  }
  return { title: text, detail: '' };
}
