import {
  type BranchChoice,
  extractInlineReasoning,
  extractVariableUpdateDiagnostics,
  formatNarrativeHtml,
  hasInlineReasoningPresetDisclosure,
  parseMessageContent,
  sanitizeReasoningText,
  selectReasoningText,
  stripStructuredBlocks,
  summarizeVariableDiagnostics,
  type VariableUpdateDiagnostics,
} from '../message-content';

export interface StoryTurnView {
  rerolling: boolean;
  rawMessage: string;
  reasoningText: string;
  inlineReasoningIncomplete: boolean;
  usesOwnDisclosure: boolean;
  storyHtml: string;
  hasNarrative: boolean;
  commentary: string;
  summary: string;
  choices: BranchChoice[];
  showRecovery: boolean;
  diagnostics: VariableUpdateDiagnostics | null;
  summaryPills: string[];
  statusLabel: string;
}

export const EMPTY_STORY_TURN_VIEW: StoryTurnView = {
  rerolling: false,
  rawMessage: '',
  reasoningText: '',
  inlineReasoningIncomplete: false,
  usesOwnDisclosure: false,
  storyHtml: '',
  hasNarrative: false,
  commentary: '',
  summary: '',
  choices: [],
  showRecovery: true,
  diagnostics: null,
  summaryPills: [],
  statusLabel: '',
};

export const formatVariableStatusLabel = (diagnostics: VariableUpdateDiagnostics | null): string => {
  if (!diagnostics) return '';
  if (!diagnostics.isComplete) return '接收中';
  if (diagnostics.parseError) return '需检错';
  return `${diagnostics.operations.length} 项`;
};

export const cleanUserActionPreview = (text: string, collapseWhitespace = false): string => {
  const stripped = stripStructuredBlocks(text).replace(/<[^>]+>/g, ' ');
  return (collapseWhitespace ? stripped.replace(/\s+/g, ' ') : stripped).trim();
};

export const checkMessageUsesOwnDisclosure = (
  rawMessage: string,
  messageId: number,
  reasoningAppearance: string,
): boolean => reasoningAppearance !== 'theme' && hasInlineReasoningPresetDisclosure(rawMessage, messageId);

export const resolveTurnReasoningText = (options: {
  rawMessage?: string;
  inlineText?: string;
  nativeReasoning?: string;
  reasoningEditable?: boolean;
  streaming?: boolean;
}): string => {
  const inlineText =
    options.inlineText !== undefined
      ? options.inlineText
      : options.rawMessage
        ? (extractInlineReasoning(options.rawMessage)?.text ?? '')
        : '';
  if (options.streaming || options.reasoningEditable) {
    return selectReasoningText(options.nativeReasoning ?? '', inlineText);
  }
  return sanitizeReasoningText(inlineText || options.nativeReasoning || '');
};

export const buildStoryTurnView = (options: {
  rawMessage: string;
  messageId: number;
  nativeReasoning?: string;
  reasoningEditable?: boolean;
  reasoningAppearance: string;
  generationNotice?: string;
  streaming?: boolean;
  rerolling?: boolean;
}): StoryTurnView => {
  const {
    rawMessage,
    messageId,
    nativeReasoning = '',
    reasoningEditable = false,
    reasoningAppearance,
    generationNotice,
    streaming = false,
    rerolling = false,
  } = options;

  const parsed = parseMessageContent(rawMessage);
  const hasNarrative = parsed.narrative.trim().length > 0;
  const diagnostics = extractVariableUpdateDiagnostics(rawMessage);
  const reasoningText = resolveTurnReasoningText({
    inlineText: parsed.reasoning?.text ?? '',
    nativeReasoning,
    reasoningEditable,
    streaming,
  });

  return {
    rerolling,
    rawMessage,
    reasoningText,
    inlineReasoningIncomplete: Boolean(parsed.reasoning?.isComplete === false),
    usesOwnDisclosure: checkMessageUsesOwnDisclosure(rawMessage, messageId, reasoningAppearance),
    storyHtml: hasNarrative ? formatNarrativeHtml(parsed.narrative, messageId) : '',
    hasNarrative,
    commentary: parsed.commentary,
    summary: parsed.summary,
    choices: parsed.choices,
    showRecovery:
      !streaming &&
      !rerolling &&
      Boolean(generationNotice || (!hasNarrative && !parsed.choices.length && !parsed.commentary && !parsed.summary)),
    diagnostics,
    summaryPills: summarizeVariableDiagnostics(diagnostics, 3),
    statusLabel: formatVariableStatusLabel(diagnostics),
  };
};
