import {
  GREETING_INDEX_CDN_IMPORT,
  GREETING_INDEX_CHANNEL,
  GREETING_INDEX_DEV_IMPORT,
  GREETING_INDEX_GLOBAL_KEY,
  GREETING_INDEX_SCRIPT_NAME,
  type GreetingIndexGlobalApi,
  type GreetingIndexMessage,
  type GreetingIndexOpenOptions,
} from '../开场白索引/protocol';

function getReadyGlobalApi(): GreetingIndexGlobalApi | null {
  try {
    const candidate = (window.parent as unknown as Record<string, unknown>)?.[GREETING_INDEX_GLOBAL_KEY] as
      | Partial<GreetingIndexGlobalApi>
      | undefined;
    if (candidate && typeof candidate.open === 'function' && (candidate.version ?? 0) >= 2) {
      return candidate as GreetingIndexGlobalApi;
    }
  } catch {
    // ignore cross-frame read errors
  }
  return null;
}

async function isLocalPreviewAvailable(): Promise<boolean> {
  try {
    const response = await fetch('http://127.0.0.1:5502/__apeiria_preview__', {
      signal: AbortSignal.timeout(600),
    });
    return response.ok;
  } catch {
    return false;
  }
}

function enableMatchingScriptInTree(
  scope: 'global' | 'character',
  preferLocalDev: boolean,
): boolean {
  let activated = false;
  updateScriptTreesWith(trees => {
    return trees.map(node => {
      if (node.type === 'script' && node.name === GREETING_INDEX_SCRIPT_NAME) {
        const isLocalContent = /127\.0\.0\.1|localhost/i.test(node.content ?? '');
        if (preferLocalDev && scope === 'global' && isLocalContent && !activated) {
          activated = true;
          return {
            ...node,
            enabled: true,
            content: GREETING_INDEX_DEV_IMPORT,
          };
        }
        if (!preferLocalDev && scope === 'character' && !activated) {
          activated = true;
          return { ...node, enabled: true };
        }
      }
      return node;
    });
  }, { type: scope });
  return activated;
}

async function ensureGreetingIndexScriptRunning(): Promise<boolean> {
  if (getReadyGlobalApi()) return true;

  const localDev = await isLocalPreviewAvailable();
  let enabled = false;

  if (localDev) {
    enabled = enableMatchingScriptInTree('global', true);
  }
  if (!enabled) {
    enabled = enableMatchingScriptInTree('character', false);
  }
  if (!enabled) {
    // 若角色卡与全局均无此脚本条目，则在角色卡脚本中自动补充
    updateScriptTreesWith(
      trees => [
        ...trees,
        {
          type: 'script',
          enabled: true,
          name: GREETING_INDEX_SCRIPT_NAME,
          id: crypto.randomUUID(),
          content: localDev ? GREETING_INDEX_DEV_IMPORT : GREETING_INDEX_CDN_IMPORT,
          info: '独立红颜画卷与开场白选定脚本',
          button: { enabled: true, buttons: [{ name: GREETING_INDEX_SCRIPT_NAME, visible: true }] },
          data: {},
          export_with: { data: true, button: true },
        },
      ],
      { type: 'character' },
    );
  }

  try {
    await Promise.race([
      waitGlobalInitialized(GREETING_INDEX_GLOBAL_KEY),
      new Promise((_, reject) => window.setTimeout(() => reject(new Error('timeout')), 4500)),
    ]);
  } catch {
    // 继续检查全局对象是否已挂载
  }
  return getReadyGlobalApi() !== null;
}

export async function openStandaloneGreetingIndex(options?: GreetingIndexOpenOptions): Promise<void> {
  const existing = getReadyGlobalApi();
  if (existing) {
    await existing.open(options);
    return;
  }

  const ready = await ensureGreetingIndexScriptRunning();
  const api = getReadyGlobalApi();
  if (ready && api) {
    await api.open(options);
    return;
  }

  try {
    const message: GreetingIndexMessage = {
      channel: GREETING_INDEX_CHANNEL,
      type: 'open',
      options,
    };
    window.parent.postMessage(message, '*');
  } catch {
    // ignore postMessage errors
  }

  if (!getReadyGlobalApi()) {
    toastr.warning('正在加载独立「开场白索引」脚本，请稍候再试或检查角色脚本启用状态。');
  }
}
