import type { ThemeId } from './themes';

export type RarityTier = 'immortal' | 'heaven' | 'earth' | 'mystic' | 'yellow' | 'mortal';
export type ThemeRarityStyle = 'starrail' | 'velvet' | 'peach' | 'classic';

export interface RarityMeta {
  tier: RarityTier;
  level: 0 | 1 | 2 | 3 | 4 | 5;
  isHighTier: boolean;
  isApexTier: boolean;
}

export const RARITY_META: Record<RarityTier, RarityMeta> = {
  mortal: { tier: 'mortal', level: 0, isHighTier: false, isApexTier: false },
  yellow: { tier: 'yellow', level: 1, isHighTier: false, isApexTier: false },
  mystic: { tier: 'mystic', level: 2, isHighTier: false, isApexTier: false },
  earth: { tier: 'earth', level: 3, isHighTier: true, isApexTier: false },
  heaven: { tier: 'heaven', level: 4, isHighTier: true, isApexTier: false },
  immortal: { tier: 'immortal', level: 5, isHighTier: true, isApexTier: true },
};

export function resolveRarityTier(rankRaw: unknown, options?: { fallbackTier?: RarityTier }): RarityTier {
  const fallback = options?.fallbackTier ?? 'mortal';
  const raw = String(rankRaw ?? '').trim();
  if (!raw || raw === '无' || raw === '未知') {
    return fallback;
  }

  const primary = raw.replace(/（[^）]*）|\([^)]*\)/gu, '').trim() || raw;

  if (/先天|道器|圣|仙|神|帝|至尊/u.test(primary)) return 'immortal';
  if (/天/u.test(primary)) return 'heaven';
  if (/地/u.test(primary)) return 'earth';
  if (/玄/u.test(primary)) return 'mystic';
  if (/黄/u.test(primary)) return 'yellow';
  if (/^凡|凡[品器物阶级]/u.test(primary)) return 'mortal';
  if (/极品灵宝|通天灵宝|后天灵宝/u.test(primary)) return 'heaven';
  if (/灵宝|法宝/u.test(primary)) return 'earth';
  if (/灵器/u.test(primary)) return 'mystic';
  if (/法器/u.test(primary)) return 'yellow';
  if (/极品/u.test(primary)) return 'heaven';
  if (/上品|珍/u.test(primary)) return 'earth';
  if (/中品/u.test(primary)) return 'mystic';
  if (/下品/u.test(primary)) return 'yellow';

  return fallback;
}

export function resolveThemeRarityStyle(themeId: ThemeId | string): ThemeRarityStyle {
  if (themeId === 'starrailGlass') return 'starrail';
  if (themeId === 'velvetOpera') return 'velvet';
  if (themeId === 'peachPudding') return 'peach';
  return 'classic';
}

export const DEFAULT_GLOW_INTENSITY = 100;

export function clampGlowIntensity(value: unknown): number {
  if (value === '' || value === null || value === undefined || typeof value === 'boolean') {
    return DEFAULT_GLOW_INTENSITY;
  }
  if (typeof value === 'string' && value.trim() === '') {
    return DEFAULT_GLOW_INTENSITY;
  }
  const num = Number(value);
  if (!Number.isFinite(num)) return DEFAULT_GLOW_INTENSITY;
  const clamped = Math.min(150, Math.max(0, Math.round(num)));
  return clamped === 0 ? 0 : clamped;
}
